use xiom.io;

enum Priority {
  Low,
  Medium,
  High,
  Urgent,
}

type Task = {
  title: Str;
  priority: Priority;
  done: Bool;
}

fn describe(t: Task) -> Str {
  let status = "INCOMPLETE";
  if t.done { status = "DONE"; }
  let label = "[LOW]";
  if t.priority == Priority.Medium { label = "[MEDIUM]"; }
  if t.priority == Priority.High { label = "[HIGH]"; }
  if t.priority == Priority.Urgent { label = "[URGENT]"; }
  return label + " " + t.title + " — " + status;
}

fn Task.complete(self) {
  done = true;
}

fn main() -> Int {
  var t1 = Task{ title: "Fix crash"; priority: Priority.Urgent; done: false; };
  var t2 = Task{ title: "Refactor"; priority: Priority.High; done: false; };
  var t3 = Task{ title: "Read docs"; priority: Priority.Low; done: false; };
  t1.complete();
  var count = 0;
  if !t1.done && t1.priority == Priority.Urgent { count = count + 1; }
  if !t2.done && t2.priority == Priority.Urgent { count = count + 1; }
  if !t3.done && t3.priority == Priority.Urgent { count = count + 1; }
  return count;
}
